+    detail: { questId: FARMER_MILL_RUN_QUEST_ID, playerId: player, rewardId: "bow_mirror" },
+  }));
+  removeEventListener("ui:questRewardError", onError);
+  removeEventListener("ui:questRewardCompleted", onCompleted);
