  assertEquals(tavern.content.monsters[0].pool[0], "rat");
  assertEquals(tavern.content.spawners[0].pool[0], "rat");
  assertEquals(tavern.content.traps.length, 0);
  assertEquals(typeof well.content.monsters[0].pool[1], "function");
