  await transitionToDepth(world, 1, crypt.pos, {
    direction: "down",
    stairPos: crypt.pos,
    templateId: crypt.entrance.templateId,
    anchorX: crypt.entrance.anchorX,
    anchorY: crypt.entrance.anchorY,
